@push('scripts')
<script>
const csrf=document.querySelector('meta[name="csrf-token"]').content, answerUrl=@json(route('candidate.exam.answer',[$round,$attempt]));
const slides=[...document.querySelectorAll('.question-slide')], navs=[...document.querySelectorAll('.q-nav')];let current=0,remaining={{ (int)$remainingSeconds }},submitting=false;
function showQuestion(index){if(!slides.length)return;current=Math.max(0,Math.min(index,slides.length-1));slides.forEach((el,i)=>el.classList.toggle('active',i===current));navs.forEach((el,i)=>el.classList.toggle('active',i===current));window.scrollTo({top:0,behavior:'smooth'});}
function updateProgress(){const checked=[...document.querySelectorAll('input[type=radio]:checked')];document.getElementById('answeredCount').textContent=checked.length;document.getElementById('progressBar').style.width=(slides.length?checked.length/slides.length*100:0)+'%';navs.forEach(n=>n.classList.toggle('answered',!!document.querySelector('input[data-question="'+n.dataset.question+'"]:checked')));}
async function saveAnswer(input){const status=document.getElementById('saved_'+input.dataset.question);status.textContent='Đang lưu đáp án...';try{const res=await fetch(answerUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({question_id:Number(input.dataset.question),option_id:Number(input.value)})});if(!res.ok)throw new Error();status.textContent='✓ Đáp án đã được lưu';updateProgress();}catch(e){status.textContent='⚠ Chưa lưu được. Vui lòng chọn lại hoặc báo giám thị.';status.style.color='#b42318';}}
document.querySelectorAll('input[type=radio]').forEach(el=>el.addEventListener('change',()=>saveAnswer(el)));navs.forEach(n=>n.addEventListener('click',()=>showQuestion(Number(n.dataset.go))));document.querySelectorAll('.prev-btn').forEach(b=>b.addEventListener('click',()=>showQuestion(current-1)));document.querySelectorAll('.next-btn').forEach(b=>b.addEventListener('click',()=>showQuestion(current+1>=slides.length?0:current+1)));
function fmt(sec){sec=Math.max(0,sec);return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')}const timer=document.getElementById('timer');timer.textContent=fmt(remaining);const tick=setInterval(()=>{remaining--;timer.textContent=fmt(remaining);if(remaining<=300)timer.style.color='#b42318';if(remaining<=0){clearInterval(tick);submitting=true;document.getElementById('submitForm').submit()}},1000);
document.getElementById('submitButton').addEventListener('click',()=>{if(submitting)return;const done=document.querySelectorAll('input[type=radio]:checked').length,missing=slides.length-done;const message=missing>0?`Bạn còn ${missing} câu chưa trả lời. Vẫn nộp bài?`:'Bạn chắc chắn muốn nộp bài?';if(confirm(message)){submitting=true;document.getElementById('submitForm').submit()}});window.addEventListener('beforeunload',e=>{if(!submitting){e.preventDefault();e.returnValue=''}});updateProgress();
</script>
@endpush